//! Enforcement test for the one-`E####`-registry decision (`docs/errors.md`):
//! every `miette::Diagnostic`-deriving enum variant across the workspace must
//! carry its own `#[diagnostic(code(...))]`, or be `#[diagnostic(transparent)]`
//! to forward an inner error's code -- never neither, which silently drops
//! the diagnostic code a `--format json` consumer or a support conversation
//! keys off. It also fails if any `callisto::<name>`-style code survives
//! anywhere in a `code(...)` attribute; every code is a numeric `E####`.
//!
//! This is a coarse, source-text scan (no `syn` dependency in this crate),
//! not a full parser -- see `strip_test_modules` and `find_enum_body` for
//! the brace-depth heuristics it relies on, which the workspace's own
//! `#[error("...")]` format strings happen to keep balanced.

use std::fs;
use std::path::PathBuf;

mod common;
use common::{collect_rust_src_files, strip_test_modules, workspace_root};

/// Every crate's `src/` directory, e.g. `crates/callisto-graph/src`.
fn all_crate_src_dirs() -> Vec<PathBuf> {
    let crates_dir = workspace_root().join("crates");
    let mut out = Vec::new();
    let Ok(entries) = fs::read_dir(&crates_dir) else {
        return out;
    };
    for entry in entries.flatten() {
        let src = entry.path().join("src");
        if src.is_dir() {
            out.push(src);
        }
    }
    out
}

/// One `pub enum Name { ... }` (or `enum Name { ... }`) block found preceded
/// by a `#[derive(...)]` mentioning `Diagnostic`.
struct DiagnosticEnum {
    name: String,
    body: String,
}

/// Finds every enum in `content` whose nearest preceding `#[derive(...)]`
/// mentions `Diagnostic` (`miette::Diagnostic` or a `use`d bare `Diagnostic`),
/// and extracts its brace-balanced body.
///
/// Relies on the workspace's own convention that `#[derive(...)]` sits
/// directly above the enum, with at most a couple of attributes
/// (`#[non_exhaustive]`, `#[allow(...)]`) in between -- true of every error
/// enum in this workspace at the time this test was written.
fn find_diagnostic_enums(content: &str) -> Vec<DiagnosticEnum> {
    let mut out = Vec::new();
    let mut search_from = 0usize;
    while let Some(derive_start) = content[search_from..].find("#[derive(") {
        let derive_start = search_from + derive_start;
        let Some(derive_end_rel) = content[derive_start..].find(")]") else {
            break;
        };
        let derive_end = derive_start + derive_end_rel + 2;
        let derive_text = &content[derive_start..derive_end];
        search_from = derive_end;

        if !derive_text.contains("Diagnostic") {
            continue;
        }

        // The enum keyword must appear within a short lookahead window (only
        // other attributes, doc comments, or whitespace in between).
        let lookahead_end = (derive_end + 400).min(content.len());
        let window = &content[derive_end..lookahead_end];
        let Some(enum_kw) = window.find("enum ") else {
            continue;
        };
        let after_kw = &window[enum_kw + "enum ".len()..];
        let name_end = after_kw.find([' ', '{', '<']).unwrap_or(after_kw.len());
        let name = after_kw[..name_end].trim().to_string();

        let Some(brace_open_rel) = window[enum_kw..].find('{') else {
            continue;
        };
        let brace_open = derive_end + enum_kw + brace_open_rel;

        // Brace-depth walk to find the matching close. Balanced within
        // `#[error("...")]` format strings (each `{field}` is itself
        // balanced), so a naive char-level count still lands correctly.
        let mut depth: i32 = 0;
        let mut close = None;
        for (offset, ch) in content[brace_open..].char_indices() {
            match ch {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        close = Some(brace_open + offset);
                        break;
                    }
                }
                _ => {}
            }
        }
        let Some(close) = close else {
            continue;
        };

        out.push(DiagnosticEnum {
            name,
            body: content[brace_open + 1..close].to_string(),
        });
        search_from = close;
    }
    out
}

/// Splits an enum body into per-variant text slices at each `#[error(`
/// occurrence -- thiserror requires every variant to carry its own
/// `#[error(...)]`, so this partitions correctly regardless of field shape.
fn split_variants(body: &str) -> Vec<&str> {
    let starts: Vec<usize> = body.match_indices("#[error(").map(|(i, _)| i).collect();
    let mut slices = Vec::new();
    for (idx, &start) in starts.iter().enumerate() {
        let end = starts.get(idx + 1).copied().unwrap_or(body.len());
        slices.push(&body[start..end]);
    }
    slices
}

/// A variant slice is compliant if it is `#[diagnostic(transparent)]`, or
/// carries its own `code(...)`. Help text is not required here -- many
/// numeric codes are documented in `docs/errors.md` with no help text by
/// design, and this test enforces the code registry, not help coverage.
fn variant_has_code_or_is_transparent(variant_text: &str) -> bool {
    variant_text.contains("#[diagnostic(transparent)]") || variant_text.contains("code(")
}

#[test]
fn every_diagnostic_variant_has_a_code_or_is_transparent() {
    let mut violations = Vec::new();
    for src_dir in all_crate_src_dirs() {
        let mut files = Vec::new();
        collect_rust_src_files(&src_dir, &mut files);
        for file in files {
            let Ok(raw) = fs::read_to_string(&file) else {
                continue;
            };
            let content = strip_test_modules(&raw);
            for diag_enum in find_diagnostic_enums(&content) {
                for variant in split_variants(&diag_enum.body) {
                    if !variant_has_code_or_is_transparent(variant) {
                        let variant_name = variant
                            .rsplit("#[")
                            .next()
                            .unwrap_or(variant)
                            .lines()
                            .find(|l| !l.trim().is_empty())
                            .unwrap_or("<unknown variant>")
                            .trim();
                        violations.push(format!(
                            "{}: enum {} has a variant with neither a code nor #[diagnostic(transparent)]: {}",
                            file.display(),
                            diag_enum.name,
                            variant_name
                        ));
                    }
                }
            }
        }
    }
    assert!(
        violations.is_empty(),
        "found error variant(s) missing a diagnostic code and not marked transparent:\n{}",
        violations.join("\n")
    );
}

#[test]
fn no_callisto_prefixed_diagnostic_codes_remain() {
    let mut violations = Vec::new();
    for src_dir in all_crate_src_dirs() {
        let mut files = Vec::new();
        collect_rust_src_files(&src_dir, &mut files);
        for file in files {
            let Ok(content) = fs::read_to_string(&file) else {
                continue;
            };
            if content.contains("code(callisto::") {
                violations.push(file.display().to_string());
            }
        }
    }
    assert!(
        violations.is_empty(),
        "found a `code(callisto::...)` diagnostic code outside the one E#### registry; \
         every diagnostic code is now numeric (see docs/errors.md): {violations:#?}"
    );
}

#[test]
fn find_diagnostic_enums_finds_a_small_fixture() {
    let src = r#"
        #[derive(Debug, thiserror::Error, miette::Diagnostic)]
        #[non_exhaustive]
        pub enum Foo {
            #[error("a")]
            #[diagnostic(code(E001), help("do it"))]
            A,
            #[error(transparent)]
            #[diagnostic(transparent)]
            B(#[from] std::io::Error),
        }
    "#;
    let enums = find_diagnostic_enums(src);
    assert_eq!(enums.len(), 1);
    assert_eq!(enums[0].name, "Foo");
    let variants = split_variants(&enums[0].body);
    assert_eq!(variants.len(), 2);
    assert!(variant_has_code_or_is_transparent(variants[0]));
    assert!(variant_has_code_or_is_transparent(variants[1]));
}

#[test]
fn detects_a_codeless_non_transparent_variant_in_a_fixture() {
    let src = r#"
        #[derive(Debug, thiserror::Error, miette::Diagnostic)]
        pub enum Foo {
            #[error("a")]
            A,
        }
    "#;
    let enums = find_diagnostic_enums(src);
    let variants = split_variants(&enums[0].body);
    assert!(!variant_has_code_or_is_transparent(variants[0]));
}
//! Each error code names one condition: a user's mistake never reports the internal-defect code, and
//! `callisto.toml` syntax errors, unknown keys and misfit values report different codes.
#[path = "common/release_harness.rs"]
mod release_harness;

use release_harness::*;

fn stderr_of(root: &std::path::Path, args: &[&str]) -> String {
    let out = callisto(root, args);
    assert!(!out.status.success(), "expected failure for {args:?}");
    String::from_utf8_lossy(&out.stderr).into_owned()
}

fn assert_only_code(stderr: &str, expected: &str) {
    for code in ["E111", "E325", "E326", "E327", "E328", "E171"] {
        assert_eq!(
            stderr.contains(code),
            code == expected,
            "{expected} only, got:\n{stderr}"
        );
    }
}

#[test]
fn pending_from_that_is_not_a_sha_is_a_user_error_not_an_internal_invariant() {
    let (dir, _) = release_commit_fixture();
    assert_only_code(&stderr_of(dir.path(), &["release", "pending", "--from", "abc"]), "E327");
}

#[test]
fn pending_from_a_commit_that_is_not_a_release_commit_is_a_user_error() {
    let (dir, _) = release_commit_fixture();
    let missing = "a".repeat(40);
    assert_only_code(
        &stderr_of(dir.path(), &["release", "pending", "--from", &missing]),
        "E328",
    );
}

fn config_error(toml: &str) -> String {
    let (dir, _) = release_commit_fixture();
    std::fs::write(dir.path().join("callisto.toml"), toml).unwrap();
    stderr_of(dir.path(), &["status"])
}

#[test]
fn config_unknown_key_reports_e325() {
    assert_only_code(&config_error("bogus = 1\n"), "E325");
    assert_only_code(&config_error("[changesets]\nbogus = 1\n"), "E325");
}

#[test]
fn config_syntax_error_reports_e111() {
    assert_only_code(&config_error("[changesets\n"), "E111");
}

#[test]
fn config_value_of_the_wrong_type_reports_e326() {
    assert_only_code(&config_error("[changesets]\ndir = 5\n"), "E326");
}

#[test]
fn every_new_code_is_documented() {
    let doc = include_str!("../../../docs/errors.md");
    for code in ["E111", "E325", "E326", "E327", "E328"] {
        assert!(
            doc.contains(&format!("| {code} |")),
            "{code} missing from docs/errors.md"
        );
    }
}

/// The error code is `expected` and neither the retired catch-all nor the internal-defect code.
fn assert_code(stderr: &str, expected: &str) {
    assert!(stderr.contains(expected), "expected {expected}, got:\n{stderr}");
    for wrong in ["E254", "E171"] {
        assert!(!stderr.contains(wrong), "{expected} expected, not {wrong}:\n{stderr}");
    }
}

#[test]
fn a_bad_publish_to_value_reports_e330() {
    let stderr = config_error("[[package]]\nmatch = \"cargo/core-crate\"\npublish-to = [\"bogus\"]\n");
    assert_code(&stderr, "E330");
    assert!(stderr.contains("bogus"), "{stderr}");
    assert_code(
        &config_error("[[package-set]]\nmatch = \"cargo/*\"\npublish-to = [\"bogus\"]\n"),
        "E330",
    );
}

#[test]
fn a_bad_release_trigger_reports_e331() {
    assert_code(
        &config_error("[[package]]\nmatch = \"cargo/core-crate\"\nrelease-trigger = \"sometimes\"\n"),
        "E331",
    );
    assert_code(
        &config_error("[[package-set]]\nmatch = \"cargo/*\"\nrelease-trigger = \"sometimes\"\n"),
        "E331",
    );
}

#[test]
fn a_bad_cascade_mode_reports_e332() {
    assert_code(&config_error("[cascade]\nmode = \"sometimes\"\n"), "E332");
}

#[test]
fn a_bad_changelog_layout_reports_e333() {
    assert_code(&config_error("[changelog]\nlayout = \"tree\"\n"), "E333");
}

#[test]
fn an_unknown_registry_kind_reports_e334() {
    assert_code(&config_error("[registries.corp]\nkind = \"maven\"\n"), "E334");
}

#[test]
fn a_publish_url_on_a_registry_that_is_not_pypi_reports_e335() {
    assert_code(
        &config_error("[registries.corp]\nkind = \"npm\"\npublish-url = \"https://corp.example.com/up\"\n"),
        "E335",
    );
}

#[test]
fn a_url_on_a_cargo_registry_reports_e336() {
    assert_code(
        &config_error("[registries.cratesIo]\nurl = \"https://corp.example.com/index\"\n"),
        "E336",
    );
}

#[test]
fn an_unusable_registry_timeout_reports_e337() {
    assert_code(&config_error("[registries.npm]\nconfirm-timeout = \"soon\"\n"), "E337");
    assert_code(&config_error("[registries.npm]\npublish-timeout = \"0s\"\n"), "E337");
}

#[test]
fn an_unparsable_package_match_reports_e338() {
    assert_code(&config_error("[[package]]\nmatch = \"cargo/a..b\"\n"), "E338");
    assert_code(&config_error("[[package-set]]\nmatch = \"cargo/[\"\n"), "E338");
}

#[test]
fn a_registry_of_the_wrong_kind_for_the_publish_target_reports_e339() {
    let (dir, _) = release_commit_fixture();
    let config = dir.path().join("callisto.toml");
    let mut text = std::fs::read_to_string(&config).unwrap();
    text.push_str("\n[registries.cratesIo]\nkind = \"npm\"\n");
    std::fs::write(config, text).unwrap();
    assert_code(&stderr_of(dir.path(), &["release", "--dry-run"]), "E339");
}

#[test]
fn every_config_value_code_is_documented() {
    let doc = include_str!("../../../docs/errors.md");
    for code in [
        "E330", "E331", "E332", "E333", "E334", "E335", "E336", "E337", "E338", "E339",
    ] {
        assert!(
            doc.contains(&format!("| {code} |")),
            "{code} missing from docs/errors.md"
        );
    }
}
//! Source-scanning helpers shared by the architecture enforcement tests.

use std::fs;
use std::path::{Path, PathBuf};

